namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = new();
    public List<string> Steps { get; set; } = new();
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Ingredients = new() { "Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil" },
            Steps = new() { "Preheat oven to 475°F.", "Roll out dough on floured surface.", "Spread crushed tomatoes evenly.", "Add torn mozzarella pieces.", "Bake 10-12 minutes until crust is golden.", "Top with fresh basil and a drizzle of olive oil." },
            AverageRating = 4.5, RatingCount = 12
        },
        new Recipe
        {
            Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
            Ingredients = new() { "Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Garlic", "Ginger" },
            Steps = new() { "Marinate chicken in yogurt and spices for 2 hours.", "Grill or pan-fry chicken until charred.", "Sauté garlic and ginger in oil.", "Add tomato sauce and simmer 10 minutes.", "Stir in cream and cooked chicken.", "Simmer 5 more minutes and serve with rice." },
            AverageRating = 4.8, RatingCount = 20
        },
        new Recipe
        {
            Id = 3, Title = "Beef Tacos", Category = "Mexican",
            Ingredients = new() { "Ground beef", "Taco shells", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Taco seasoning" },
            Steps = new() { "Brown ground beef in a skillet.", "Add taco seasoning and water, simmer 5 minutes.", "Warm taco shells in oven.", "Assemble tacos with beef and toppings.", "Serve immediately." },
            AverageRating = 4.2, RatingCount = 8
        },
        new Recipe
        {
            Id = 4, Title = "Spaghetti Carbonara", Category = "Italian",
            Ingredients = new() { "Spaghetti", "Pancetta", "Eggs", "Parmesan cheese", "Black pepper" },
            Steps = new() { "Cook spaghetti until al dente.", "Fry pancetta until crispy.", "Whisk eggs with grated parmesan.", "Toss hot pasta with pancetta.", "Remove from heat, stir in egg mixture.", "Season with black pepper and serve." },
            AverageRating = 4.6, RatingCount = 15
        },
        new Recipe
        {
            Id = 5, Title = "Pad Thai", Category = "Thai",
            Ingredients = new() { "Rice noodles", "Shrimp", "Tofu", "Bean sprouts", "Peanuts", "Lime", "Fish sauce", "Tamarind paste" },
            Steps = new() { "Soak rice noodles in warm water 30 minutes.", "Make sauce: mix tamarind paste, fish sauce, and sugar.", "Stir-fry shrimp and tofu until cooked.", "Add drained noodles and sauce to wok.", "Toss with bean sprouts.", "Serve topped with peanuts and lime wedge." },
            AverageRating = 4.4, RatingCount = 10
        },
        new Recipe
        {
            Id = 6, Title = "Guacamole", Category = "Mexican",
            Ingredients = new() { "Avocados", "Lime juice", "Red onion", "Cilantro", "Jalapeño", "Salt" },
            Steps = new() { "Halve and pit avocados.", "Mash avocado flesh in a bowl.", "Stir in diced onion, cilantro, and jalapeño.", "Add lime juice and salt to taste.", "Serve with tortilla chips." },
            AverageRating = 4.7, RatingCount = 18
        }
    };

    private int _nextId = 7;

    public List<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public List<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
    }

    public void AddRecipe(RecipeSubmission submission)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = submission.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            AverageRating = 0,
            RatingCount = 0
        });
    }
}

