<PageTitle>RecipeShare - Home</PageTitle>

<div class="container py-4">
    <div class="text-center mb-5">
        <h1 class="display-4">🍳 RecipeShare</h1>
        <p class="lead text-muted">Discover and share delicious recipes from around the world</p>
    </div>

    <h2 class="mb-4">Browse by Category</h2>
    <div class="row g-4">
        @foreach (var category in Categories)
        {
            <div class="col-md-4">
                <div class="card h-100 shadow-sm">
                    <div class="card-body text-center">
                        <h3 class="card-title">@GetEmoji(category) @category</h3>
                        <p class="card-text text-muted">Explore our @category recipes</p>
                        <a href="/category/@category" class="btn btn-outline-primary">Browse Recipes</a>
                    </div>
                </div>
            </div>
        }
    </div>

    <div class="text-center mt-5">
        <a href="/submit" class="btn btn-success btn-lg">📝 Submit Your Recipe</a>
    </div>
</div>

@code {
    [Inject] private RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private List<string> Categories = new();

    protected override void OnInitialized()
    {
        Categories = RecipeService.GetCategories();
    }

    private string GetEmoji(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Mexican" => "🌮",
        "Thai" => "🍜",
        _ => "🍽️"
    };
}

